from format_lecon import paras,table
from medicaments import quote

def tobrex(l,contexte='orgelet'):
 d=paras('La tobramycine est un aminoglycoside qui inhibe la synthèse des protéines bactériennes. Elle n’agit pas sur une obstruction glandulaire stérile. La préparation choisie ici est Tobrex pommade ophtalmique, à 3 mg/g, tube de 3,5 g, autorisation suisse 45508. Le document partagé avec le collyre porte aussi le numéro 44538 ; les deux formes ont été vérifiées dans la liste Swissmedic du 30 septembre 2026.',
 'La notice de juillet 2020 couvre les infections bactériennes sensibles du segment antérieur et des annexes. Elle ne nomme pas séparément l’orgelet. Le choix pour une présentation franche d’orgelet repose sur la stratégie HUG 2025 ; il ne constitue pas une indication automatique pour toute paupière gonflée.')
 d+=quote('44538',["Infections du segment antérieur", "Tobrex pommade ophtalmique: 3 mg", "En cas d'infections légères à modérées, appliquer"])
 d+=paras('Pour une infection légère à modérée, la notice de la pommade prévoit environ 1,5 cm dans le sac conjonctival de l’œil atteint, deux à trois fois par jour. Le guide HUG propose deux applications quotidiennes pendant sept jours pour l’orgelet franc. La fréquence est compatible avec la notice ; la durée de sept jours vient du guide, car la notice citée ne fixe pas de durée spécifique d’orgelet.',
 'La phrase officielle contient aussi un rythme intensifié pour les infections graves. Elle ne permet pas de traiter une cellulite orbitaire ou une infection profonde par pommade seule. Dans ce contexte, l’évaluation urgente et le traitement systémique ont priorité.',
 'L’embout ne touche ni cils ni peau. Déposer la pommade selon la démonstration du soignant, sans pression sur le nodule. Un voile visuel transitoire est possible : attendre le retour d’une vision normale avant conduite. Une baisse persistante ou douloureuse doit être examinée.')
 d+='<h3>Enfant : distinguer impérativement les deux formes</h3>'
 d+=quote('44538',["Des études cliniques ont montré", "L'expérience documentée chez les nourrissons", "Ce médicament contient du bore"])
 d+=paras('La pommade n’est pas recommandée avant deux mois ; dès cet âge, la notice ne demande pas d’ajustement pédiatrique. Cela ne transforme pas une infection néonatale en situation d’automédication. Le collyre contient du bore et ses restrictions particulières priment sur la phrase générale : ne pas l’utiliser avant deux ans, ni avant douze ans en cas d’infection grave. Ne pas substituer les gouttes à la pommade en reprenant le seul seuil de deux mois.')
 d+='<h3>Contre-indications et précautions</h3>'
 d+=quote('44538',["Hypersensibilité connue à la substance", "Hypersensibilité connue à d'autres", "Certains patients peuvent présenter", "La prudence est de rigueur lorsque Tobrex", "Si l'on utilise Tobrex simultanément"])
 d+=paras('Rechercher une allergie aux aminoglycosides ou aux excipients avant prescription. Arrêter en cas d’hypersensibilité, puis évaluer immédiatement une réaction respiratoire ou généralisée. Une aggravation de l’œdème peut être une réaction au produit autant qu’un échec infectieux.',
 'Les patients atteints de myasthénie ou d’une autre maladie neuromusculaire demandent une prudence particulière. Une association avec un aminoglycoside systémique nécessite une attention aux concentrations sanguines et aux toxicités rénale, auditive et neurologique. La notice ne donne pas de tableau d’ajustement rénal ou hépatique pour cette pommade : ne pas inventer une réduction en centimètres à partir des doses intraveineuses.',
 'Limiter le traitement à l’épisode et à la durée prescrite. Une utilisation prolongée favorise la sélection de germes résistants et de champignons. Aucun remplacement empirique par un autre antibiotique n’est proposé sans réexamen ; une allergie impose de choisir une autre option avec sa propre notice.')
 d+='<h3>Grossesse et allaitement</h3>'
 d+=quote('44538',["Il n'existe pas de données suffisantes", "Les expérimentations animales effectuées", "Administrée par voie intraveineuse", "Pendant la grossesse, Tobrex", "La tobramycine est excrétée", "On ne sait pas si la tobramycine", "Ainsi, en f"])
 d+=paras('La notice réserve l’utilisation pendant la grossesse aux indications impératives et exceptionnelles. Pendant l’allaitement, elle demande de choisir selon la situation entre arrêt du médicament et arrêt de l’allaitement. Pour une lésion souvent accessible aux soins locaux, réévaluer d’abord l’utilité du produit avec le prescripteur ; ne pas imposer un sevrage automatique sans cette discussion.')
 d+='<h3>Utilisation et suivi</h3>'
 d+=quote('44538',["Le collyre et la pommade ophtalmique", "Ne pas porter de lentilles de contact pendant", "Ne pas utiliser le contenu plus longtemps", "Afin d'éviter toute contamination"])
 d+=paras('Les applications de produits ophtalmiques différents sont espacées de cinq à dix minutes selon la notice. Ne pas porter de lentilles pendant le traitement et l’épisode inflammatoire. La limite de conservation de trente jours après ouverture n’est pas une durée de traitement.',
 'Vérifier indication, forme 45508, allergies, âge, grossesse/allaitement, autres traitements et possibilité de contrôle. Rechercher la diminution de douleur et de rougeur sans apparition de signe visuel ou orbitaire. Une absence d’amélioration à trois jours selon HUG, ou toute aggravation avant ce délai, impose une réévaluation spécialisée.')
 if contexte=='blepharite':
  d=d.replace('Elle ne nomme pas séparément l’orgelet. Le choix pour une présentation franche d’orgelet repose sur la stratégie HUG 2025 ; il ne constitue pas une indication automatique pour toute paupière gonflée.', 'La blépharite figure parmi les indications lorsque des bactéries sensibles sont en cause. Le choix pour une composante bactérienne antérieure repose sur la stratégie HUG 2025 ; il ne traite pas à lui seul toute blépharite inflammatoire ou liée à Demodex.')
  d=d.replace('Le guide HUG propose deux applications quotidiennes pendant sept jours pour l’orgelet franc. La fréquence est compatible avec la notice ; la durée de sept jours vient du guide, car la notice citée ne fixe pas de durée spécifique d’orgelet.', 'Le guide HUG propose deux applications quotidiennes pendant dix jours pour la composante infectieuse de la blépharite antérieure. La fréquence est compatible avec la notice ; la durée de dix jours vient du guide, car la notice citée ne fixe pas de durée spécifique de blépharite.')
  d=d.replace('Une absence d’amélioration à trois jours selon HUG, ou toute aggravation avant ce délai, impose une réévaluation spécialisée.', 'Une absence de réponse au traitement correctement conduit, une récidive préoccupante ou une aggravation impose une réévaluation spécialisée. Un symptôme visuel, une photophobie ou une douleur importante ne doit pas attendre la fin de la cure.')
  assert 'orgelet' not in d
 return l.subwindow('tobrex','Tobramycine : pommade suisse, doses et restrictions',d,(18,22))
